@MainActor func transient_CommentInSchematic_selectionDisplay (
       _ prefs_selectionHiliteColor : NSColor,                 
       _ self_mComment : String,                               
       _ self_mColor : NSColor,                                
       _ self_mSize : Double,                                  
       _ self_mHorizontalAlignment : HorizontalAlignment,      
       _ self_mVerticalAlignment : VerticalAlignment,          
       _ prefs_schematicBackColor : NSColor,                   
       _ self_mRotation : CanariAngle,                         
       _ self_mBold : Bool,                                    
       _ self_mX : CanariLength,                               
       _ self_mY : CanariLength
) -> EBShape {
//--- START OF USER ZONE 2
        let s = CGFloat (self_mSize)
        let font = self_mBold ? NSFont.boldSystemFont (ofSize: s) : NSFont.systemFont (ofSize: s)
    //    let p = NSPoint (x: self_mX, y: self_mY)
        let af = CanariAffinity.translating (x: self_mX, y: self_mY).rotating (by: self_mRotation)
        var shape = EBShape ()
        shape.add (
          textKnob: (self_mComment.isEmpty) ? "Empty comment" : self_mComment,
          NSPoint (),
          font,
          foreColor: self_mColor,
          backColor: prefs_schematicBackColor,
          self_mHorizontalAlignment.ebTextShapeHorizontalAlignment,
          self_mVerticalAlignment.ebTextShapeVerticalAlignment,
          .rect,
          knobIndex: 0
        )
        shape.add (knobAt: CanariPoint (), knobIndex: COMMENT_IN_SCHEMATIC_DRAG_KNOB, .rect, SCHEMATIC_KNOB_SIZE)
        shape.add (knobAt: CanariPoint (x: .pt (shape.boundingBox.width) / 2.0), knobIndex: COMMENT_IN_SCHEMATIC_ROTATION_KNOB, .circ, SCHEMATIC_KNOB_SIZE)
        let rotatedShape = shape.transformed (by: af)
        return rotatedShape
//--- END OF USER ZONE 2
}

